{
  "name": "SCPI通用仪器软件接口",
  "name_en": "Generic SCPI Instrument Software Interface",
  "manufacturer": "",
  "description": "这是一个非物理的软件组件，用于在实验中以统一方式连接和访问支持 SCPI 命令的仪器。它提供端口、资源标识和连接参数管理，以及通用的写入、读取、查询、复位和初始化操作，适合用于构建各类仪器的上层控制流程。",
  "description_en": "This is a non-physical software component for uniformly connecting to and accessing instruments that support SCPI commands in laboratory workflows. It manages ports, resource identifiers, and connection parameters, and provides generic write, read, query, reset, and initialization operations for higher-level instrument control.",
  "tag_hints": [
    "SCPI control",
    "instrument communication",
    "generic instrument abstraction",
    "VISA resource access",
    "port configuration",
    "query/read/write messaging"
  ],
  "actions": [
    {
      "action_name": "auto-backend",
      "description": "获取通信后端",
      "description_en": "get the communication backend"
    },
    {
      "action_name": "auto-instrument",
      "description": "获取仪器接口对象",
      "description_en": "get the instrument interface object"
    },
    {
      "action_name": "auto-port",
      "description": "获取或设置通信端口",
      "description_en": "get or set the communication port"
    },
    {
      "action_name": "auto-port_match",
      "description": "获取或设置连接时是否要求端口匹配已发现资源",
      "description_en": "get or set whether port matching to a discovered resource is required when connecting"
    },
    {
      "action_name": "auto-rid",
      "description": "获取或设置资源标识",
      "description_en": "get or set the resource identifier"
    },
    {
      "action_name": "auto-resource_params",
      "description": "获取资源连接参数",
      "description_en": "get the resource connection parameters"
    },
    {
      "action_name": "auto-id",
      "description": "获取仪器标识",
      "description_en": "get the instrument identification"
    },
    {
      "action_name": "auto-value",
      "description": "获取当前值",
      "description_en": "get the current value"
    },
    {
      "action_name": "auto-connected",
      "description": "获取连接状态",
      "description_en": "get the connection status"
    },
    {
      "action_name": "auto-is_connected",
      "description": "获取连接状态",
      "description_en": "get the connection status"
    },
    {
      "action_name": "auto-write",
      "description": "向已连接资源写入消息",
      "description_en": "write a message to the connected resource"
    },
    {
      "action_name": "auto-read",
      "description": "从已连接资源读取响应",
      "description_en": "read a response from the connected resource"
    },
    {
      "action_name": "auto-query",
      "description": "发送查询并返回响应",
      "description_en": "send a query and return the response"
    },
    {
      "action_name": "auto-reset",
      "description": "发送复位命令",
      "description_en": "send a reset command"
    },
    {
      "action_name": "auto-init",
      "description": "发送初始化命令",
      "description_en": "send the initialization command"
    }
  ]
}

